-- QUIZ HUBT ONLINE - ONE FILE MYSQL INITIALIZER
-- Source: online Java/Spring Boot project 3.0.0 (not the offline 4.0 app).
-- Exported 2026-11-18. Requires MySQL 8.0.16+ / 8.4, utf8mb4.
-- MySQL Workbench: File > Open SQL Script > select this file > Execute All.
-- This script creates jlerTestingHubt + 8 tables + 39 exams / 8632 questions.
-- School/major/question metadata and optional image paths are preserved as JSON.
-- It does NOT contain image files, user uploads, or personal account/history data.
-- Existing catalog documents and accounts are kept (INSERT IGNORE).
-- No DROP DATABASE / DROP TABLE / TRUNCATE statements.
-- Initial accounts are only added if absent; existing passwords are NOT reset.
-- Fresh DB admin: admin@jler.local / Admin@123
-- Fresh DB student: DEMO001 (or student@jler.local) / Student@123
-- Passwords are BCrypt hashes compatible with the online Spring backend.
-- Change the initial demo passwords before using a publicly deployed service.
-- Important: importing SQL alone does not run the backend/frontend.
-- Configure the ONLINE backend datasource to jlerTestingHubt and start it.
-- The OFFLINE Android app does not connect to this database.

SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS jlerTestingHubt CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE jlerTestingHubt;

CREATE TABLE IF NOT EXISTS app_users (
 id VARCHAR(64) PRIMARY KEY,
 name VARCHAR(200) NOT NULL,
 email VARCHAR(254) NOT NULL UNIQUE,
 student_code VARCHAR(64) UNIQUE,
 school_id VARCHAR(128) NULL,
  class_name VARCHAR(100) NOT NULL DEFAULT '',
 password_hash VARCHAR(100) NOT NULL,
 role VARCHAR(16) NOT NULL,
 status VARCHAR(16) NOT NULL DEFAULT 'active',
 deleted BOOLEAN NOT NULL DEFAULT FALSE,
 created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 CHECK (role IN ('ADMIN','STUDENT')),
 CHECK (status IN ('active','blocked'))
);
CREATE TABLE IF NOT EXISTS login_sessions (
 id VARCHAR(36) PRIMARY KEY,
 user_id VARCHAR(64) NOT NULL,
 expires_at DATETIME(6) NOT NULL,
 revoked BOOLEAN NOT NULL DEFAULT FALSE,
 revoked_reason VARCHAR(24),
 INDEX idx_login_user(user_id)
);
CREATE TABLE IF NOT EXISTS refresh_tokens (
 hash CHAR(64) PRIMARY KEY,
 session_id VARCHAR(36) NOT NULL,
 used BOOLEAN NOT NULL DEFAULT FALSE,
 INDEX idx_refresh_session(session_id)
);
-- Versioned JSON documents preserve question text, order, optional fields and image paths.
CREATE TABLE IF NOT EXISTS catalog_documents (
 kind VARCHAR(24) NOT NULL,
 id VARCHAR(128) NOT NULL,
 body JSON NOT NULL,
 revision BIGINT NOT NULL DEFAULT 1,
 created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 PRIMARY KEY(kind,id),
 CHECK (kind IN ('majors','exams','notifications','keys','submissions','settings','schools','topics','pages'))
);
CREATE TABLE IF NOT EXISTS exam_attempts (
 id CHAR(36) PRIMARY KEY,
 user_id VARCHAR(64) NOT NULL,
 exam_id VARCHAR(128) NOT NULL,
 snapshot JSON NOT NULL,
 result JSON,
 retry BOOLEAN NOT NULL DEFAULT FALSE,
 status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
 created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 submitted_at TIMESTAMP(6) NULL,
 hidden BOOLEAN NOT NULL DEFAULT FALSE,
 FOREIGN KEY(user_id) REFERENCES app_users(id),
 CHECK (status IN ('ACTIVE','SUBMITTED','ABANDONED')),
 INDEX idx_attempt_owner(user_id,status,created_at)
);
CREATE TABLE IF NOT EXISTS key_redemptions (
 user_id VARCHAR(64) NOT NULL PRIMARY KEY,
 key_id VARCHAR(128) NOT NULL,
 redeemed_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 FOREIGN KEY(user_id) REFERENCES app_users(id)
);
CREATE TABLE IF NOT EXISTS notification_reads (
 user_id VARCHAR(64) NOT NULL,
 notification_id VARCHAR(128) NOT NULL,
 PRIMARY KEY(user_id,notification_id),
 FOREIGN KEY(user_id) REFERENCES app_users(id) ON DELETE CASCADE
);

INSERT IGNORE INTO catalog_documents(kind,id,body) VALUES('settings','key_mutex','{}');

CREATE TABLE IF NOT EXISTS password_reset_challenges (
 id VARCHAR(36) PRIMARY KEY,
 user_id VARCHAR(64),
 email_hash VARCHAR(64) NOT NULL,
 ip_hash VARCHAR(64) NOT NULL,
 otp_hash VARCHAR(64) NOT NULL,
 reset_hash VARCHAR(64),
 created_at DATETIME(6) NOT NULL,
 expires_at DATETIME(6) NOT NULL,
 attempts INT NOT NULL DEFAULT 0,
 consumed BOOLEAN NOT NULL DEFAULT FALSE,
 INDEX ix_reset_email_created(email_hash,created_at),
 INDEX ix_reset_ip_created(ip_hash,created_at)
);

-- Compatibility with online DB versions created before school selection.
SET @school_column_ddl = IF(
 (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='app_users' AND COLUMN_NAME='school_id')=0,
 'ALTER TABLE app_users ADD COLUMN school_id VARCHAR(128) NULL',
 'SELECT ''app_users.school_id already exists'' AS message');
PREPARE school_column_upgrade FROM @school_column_ddl;
EXECUTE school_column_upgrade;
DEALLOCATE PREPARE school_column_upgrade;

-- MySQL 8.0.16+ / 8.4. Run only against the existing jlerTestingHubt database.
-- Keeps every table, row, ID and JSON document. Widens an old CHECK constraint.
USE jlerTestingHubt;
SET @catalog_exists = (SELECT COUNT(*) FROM information_schema.TABLES
 WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'catalog_documents');
SET @drop_checks = (
 SELECT GROUP_CONCAT(CONCAT('DROP CHECK `',REPLACE(tc.CONSTRAINT_NAME,'`','``'),'`') SEPARATOR ', ')
 FROM information_schema.TABLE_CONSTRAINTS tc
 JOIN information_schema.CHECK_CONSTRAINTS cc
 ON cc.CONSTRAINT_SCHEMA = tc.CONSTRAINT_SCHEMA AND cc.CONSTRAINT_NAME = tc.CONSTRAINT_NAME
 WHERE tc.TABLE_SCHEMA = DATABASE() AND tc.TABLE_NAME = 'catalog_documents'
 AND tc.CONSTRAINT_TYPE = 'CHECK' AND LOWER(cc.CHECK_CLAUSE) LIKE '%kind%'
);
SET @catalog_ddl = IF(@catalog_exists = 0,
 'SELECT ''catalog_documents is not created yet; JPA will create it.'' AS message',
 CONCAT('ALTER TABLE `catalog_documents` ',
 IF(@drop_checks IS NULL,'',CONCAT(@drop_checks,', ')),
 'ADD CONSTRAINT `ck_catalog_kind_v2` CHECK (`kind` IN (''majors'',''exams'',''notifications'',''keys'',''submissions'',''settings'',''schools'',''topics'',''pages''))'));
PREPARE catalog_upgrade FROM @catalog_ddl;
EXECUTE catalog_upgrade;
DEALLOCATE PREPARE catalog_upgrade;

